begin;
-- Real synthetic sessions for member JWT fixtures; rows roll back with this test.
insert into auth.sessions(id,user_id) select md5('pgtap-session:'||id::text)::uuid,id from auth.users;
set local search_path=extensions,public,private;
select no_plan();
update private.private_locations set verified_at=now() where profile_id::text like '10000000-%';
insert into public.conversations(id,participant_low,participant_high,created_by) values('91000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000001');
insert into public.conversation_members(conversation_id,user_id) values('91000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001'),('91000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000002');
insert into public.albums(id,owner_id,name) values('91000000-0000-4000-8000-000000000002','10000000-0000-0000-0000-000000000001','Renewal test');
insert into public.album_shares(id,album_id,owner_id,recipient_id,conversation_id,access_mode,status,shared_version,accepted_at)
values('91000000-0000-4000-8000-000000000003','91000000-0000-4000-8000-000000000002','10000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','91000000-0000-4000-8000-000000000001','view_once','accepted',1,now());
select ok(not has_function_privilege('anon','public.refresh_album_share(uuid,uuid)','execute'),'anonymous viewer renewal denied');
select ok(not has_function_privilege('anon','public.resolve_notification(uuid)','execute'),'anonymous notification resolution denied');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000002','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000002')::uuid))::text,true);
select set_config('request.jwt.claim.role','authenticated',true);
select set_config('test.viewer',public.open_album_share_once('91000000-0000-4000-8000-000000000003','92000000-0000-4000-8000-000000000001')::text,true);
select is(public.open_album_share_once('91000000-0000-4000-8000-000000000003','92000000-0000-4000-8000-000000000001')->>'session_id',current_setting('test.viewer')::jsonb->>'session_id','lost acknowledgement retries reuse the original view-once session');
select is(public.refresh_album_share('91000000-0000-4000-8000-000000000003',(current_setting('test.viewer')::jsonb->>'session_id')::uuid)->>'session_expires_at',current_setting('test.viewer')::jsonb->>'session_expires_at','renewal does not extend the viewing period');
select throws_ok($$select public.open_album_share_once('91000000-0000-4000-8000-000000000003','92000000-0000-4000-8000-000000000002')$$,'42501','album_already_viewed','another opening cannot consume the share twice');
select throws_ok($$select public.refresh_album_share('91000000-0000-4000-8000-000000000003',null)$$,'42501','album_share_locked','view-once renewal requires the correct session');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000003','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000003')::uuid))::text,true);
select throws_ok($$select public.refresh_album_share('91000000-0000-4000-8000-000000000003',(current_setting('test.viewer')::jsonb->>'session_id')::uuid)$$,'42501','album_share_locked','another account cannot reuse a viewing session');
reset role;
select is((select count(*) from public.album_view_sessions where share_id='91000000-0000-4000-8000-000000000003'),1::bigint,'exactly one viewing session exists');
update public.album_view_sessions set expires_at=now()-interval '1 second' where share_id='91000000-0000-4000-8000-000000000003';
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000002','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000002')::uuid))::text,true);
select throws_ok($$select public.refresh_album_share('91000000-0000-4000-8000-000000000003',(current_setting('test.viewer')::jsonb->>'session_id')::uuid)$$,'42501','album_share_locked','expired session cannot renew URLs');
reset role;
update public.album_view_sessions set expires_at=now()+interval '5 minutes' where share_id='91000000-0000-4000-8000-000000000003';
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000001','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000001')::uuid))::text,true);
select lives_ok($$select public.revoke_album_share('91000000-0000-4000-8000-000000000003')$$,'owner can revoke an open viewer');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000002','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000002')::uuid))::text,true);
select throws_ok($$select public.refresh_album_share('91000000-0000-4000-8000-000000000003',(current_setting('test.viewer')::jsonb->>'session_id')::uuid)$$,'42501','album_share_locked','revoked share cannot renew URLs');
reset role;

insert into public.messages(id,conversation_id,sender_id,body) values('93000000-0000-4000-8000-000000000001','91000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','Sensitive message must stay out of push');
select is((select count(*) from public.notifications where direct_message_id='93000000-0000-4000-8000-000000000001'),1::bigint,'direct message notifies only the recipient');
select is((select payload from public.notifications where direct_message_id='93000000-0000-4000-8000-000000000001'),'{}'::jsonb,'notification stores no message body');
select set_config('test.direct_notification',(select id::text from public.notifications where direct_message_id='93000000-0000-4000-8000-000000000001'),true);
select is((select count(*) from private.notification_outbox where notification_id=current_setting('test.direct_notification')::uuid),1::bigint,'direct message has a durable push job');
insert into public.messages(id,conversation_id,sender_id,body,media_status) values('93000000-0000-4000-8000-000000000002','91000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','[media_pending]','pending');
select is((select count(*) from public.notifications where direct_message_id='93000000-0000-4000-8000-000000000002'),0::bigint,'quarantined image never sends a push');
update public.messages set media_status='approved' where id='93000000-0000-4000-8000-000000000002';
update public.messages set media_status='approved' where id='93000000-0000-4000-8000-000000000002';
select is((select count(*) from public.notifications where direct_message_id='93000000-0000-4000-8000-000000000002'),1::bigint,'approved media publication and repeated worker result enqueue only once');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000002','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000002')::uuid))::text,true);
select is(public.resolve_notification(current_setting('test.direct_notification')::uuid)->>'type','conversation','recipient resolves an authorized conversation');
select is(public.resolve_notification(current_setting('test.direct_notification')::uuid)->>'profileId','10000000-0000-0000-0000-000000000001','authorized chat deep link retains report and album controls');
select is(jsonb_array_length(public.list_notifications(200)),0,'meetup-only inbox excludes chat notifications');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000003',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000003','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000003')::uuid))::text,true);
select throws_ok($$select public.resolve_notification(current_setting('test.direct_notification')::uuid)$$,'42501','notification_unavailable','outsider cannot resolve another account notification');
reset role;
insert into public.groups(id,owner_id,name) values('94000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','Private group');
insert into public.group_members(group_id,profile_id,role,status) values
 ('94000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','owner','active'),
 ('94000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000002','member','active'),
 ('94000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000003','member','invited');
insert into public.group_messages(id,group_id,sender_id,body) values('94000000-0000-4000-8000-000000000002','94000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000001','Private group message');
select is((select count(*) from public.notifications where group_message_id='94000000-0000-4000-8000-000000000002'),1::bigint,'group message excludes sender and unaccepted invitee');
select set_config('test.group_notification',(select id::text from public.notifications where group_message_id='94000000-0000-4000-8000-000000000002'),true);
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000002',true);
select set_config('request.jwt.claims',(coalesce(nullif(current_setting('request.jwt.claims',true),''),'{}')::jsonb||jsonb_build_object('sub','10000000-0000-0000-0000-000000000002','session_id',md5('pgtap-session:10000000-0000-0000-0000-000000000002')::uuid))::text,true);
select is(public.resolve_notification(current_setting('test.group_notification')::uuid)->>'type','group','active member resolves a group target');
reset role;
update public.group_members set status='removed' where group_id='94000000-0000-4000-8000-000000000001' and profile_id='10000000-0000-0000-0000-000000000002';
set local role authenticated;
select throws_ok($$select public.resolve_notification(current_setting('test.group_notification')::uuid)$$,'42501','notification_unavailable','removed member cannot follow an old group push');
reset role;
insert into auth.sessions(id,user_id) values('95000000-0000-4000-8000-000000000001','10000000-0000-0000-0000-000000000002');
set local role authenticated;
select set_config('request.jwt.claims','{"session_id":"95000000-0000-4000-8000-000000000001"}',true);
select lives_ok($$select public.register_push_token('ExponentPushToken[delivery-fixture]','ios','en')$$,'active session registers a device');
reset role;
select is((select auth_session_id from private.push_tokens where expo_push_token='ExponentPushToken[delivery-fixture]'),'95000000-0000-4000-8000-000000000001'::uuid,'token binds to server auth session');
insert into public.blocks(blocker_id,blocked_id) values('10000000-0000-0000-0000-000000000002','10000000-0000-0000-0000-000000000001');
set local role authenticated;
select throws_ok($$select public.resolve_notification(current_setting('test.direct_notification')::uuid)$$,'42501','notification_unavailable','block revokes old direct-message deep link');
reset role;
set local role service_role;
select set_config('request.jwt.claim.role','service_role',true);
select set_config('test.claim',public.claim_notification_outbox(100,'96000000-0000-4000-8000-000000000001')::text,true);
reset role;
select is((select coalesce(sum(jsonb_array_length(x->'tokens')),0)::bigint from jsonb_array_elements(current_setting('test.claim')::jsonb) x where x->'notification'->>'id' in(current_setting('test.direct_notification'),current_setting('test.group_notification'))),0::bigint,'queued pushes recheck block and removed-group authorization before delivery');
delete from auth.sessions where id='95000000-0000-4000-8000-000000000001';
select is((select count(*) from private.push_tokens where expo_push_token='ExponentPushToken[delivery-fixture]'),0::bigint,'server sign-out removes the token even if the device is offline');
set local role authenticated;
select set_config('request.jwt.claim.role','authenticated',true);
select throws_ok($$select public.register_push_token('ExponentPushToken[delivery-fixture]','ios','en')$$,'42501','active_session_required','signed-out JWT cannot register push again');
select * from finish();
rollback;
